import math

def solve_case(case):
    n = case['n']
    decimals = case.get('decimals', 0)
    base = case.get('base', math.pi)
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if n == 0:
        if decimals == 0:
            return '0'
        return '0.' + '0' * decimals
    sign = '-' if n < 0 else ''
    x = abs(n)
    int_digits = []
    if x >= 1.0:
        k = 0
        while base ** (k + 1) <= x:
            k += 1
        for i in range(k, -1, -1):
            pow_val = base ** i
            d = int(math.floor(x / pow_val))
            if d >= base:
                d = int(base) - 1
            if d < 0:
                d = 0
            int_digits.append(d)
            x -= d * pow_val
            if x < 0:
                x = 0.0
    else:
        int_digits.append(0)
    frac_digits = []
    for _ in range(decimals):
        x *= base
        d = int(math.floor(x))
        if d >= base:
            d = int(base) - 1
        if d < 0:
            d = 0
        frac_digits.append(d)
        x -= d
        if x < 0:
            x = 0.0
    int_str = ''.join(chars[d] for d in int_digits)
    if decimals > 0:
        frac_str = ''.join(chars[d] for d in frac_digits)
        return sign + int_str + '.' + frac_str
    return sign + int_str

from collections import Counter

def solve_case(case):
    s1 = case['s1']
    s2 = case['s2']
    c1 = Counter(ch for ch in s1 if 'a' <= ch <= 'z')
    c2 = Counter(ch for ch in s2 if 'a' <= ch <= 'z')
    parts = []
    for ch in 'abcdefghijklmnopqrstuvwxyz':
        m1 = c1.get(ch, 0)
        m2 = c2.get(ch, 0)
        mx = max(m1, m2)
        if mx <= 1:
            continue
        if m1 == mx and m2 == mx:
            pref = '=:'
        elif m1 == mx:
            pref = '1:'
        else:
            pref = '2:'
        parts.append(pref + ch * mx)
    parts.sort(key=lambda x: (-len(x), x))
    return '/'.join(parts)

