from collections import defaultdict

def solve_case(case):
    s = case['poly']
    coeffs = defaultdict(int)
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '+':
            sign = 1
            i += 1
        elif s[i] == '-':
            sign = -1
            i += 1
        else:
            sign = 1
        num_str = ''
        while i < n and s[i].isdigit():
            num_str += s[i]
            i += 1
        coeff = sign * int(num_str) if num_str else sign
        vars_list = []
        while i < n and s[i].islower():
            vars_list.append(s[i])
            i += 1
        key = ''.join(sorted(vars_list))
        coeffs[key] += coeff
    items = [(k, c) for k, c in coeffs.items() if c != 0]
    items.sort(key=lambda x: (len(x[0]), x[0]))
    parts = []
    for idx, (k, c) in enumerate(items):
        if c == 1:
            term = k
        elif c == -1:
            term = '-' + k
        else:
            term = str(c) + k
        if idx == 0:
            parts.append(term)
        else:
            parts.append(('+' + term) if c > 0 else term)
    return ''.join(parts)

def solve_case(case):
    tokens = case["frames"].split()
    rolls = []
    for t in tokens:
        for ch in t:
            if ch == 'X':
                rolls.append(10)
            elif ch == '/':
                rolls.append(10 - rolls[-1])
            else:
                rolls.append(int(ch))
    total = 0
    idx = 0
    for i in range(9):
        tk = tokens[i]
        if tk == 'X':
            total += 10 + rolls[idx+1] + rolls[idx+2]
            idx += 1
        elif '/' in tk:
            total += 10 + rolls[idx+2]
            idx += 2
        else:
            total += rolls[idx] + rolls[idx+1]
            idx += 2
    total += sum(rolls[idx:])
    return total
